async function saveDrafts() {
  console.log('--- Saving 10 CareerDost Article Packages as DRAFTS ---')

  const stmtArtInsert = db.prepare(`
    INSERT INTO articles (
      slug, title, category_slug, organization, job_type, location,
      qualification, salary, experience, positions, last_date, no_deadline,
      publish_date, official_link, apply_link, is_verified, featured,
      logo_initial, featured_image, image_alt, excerpt, content,
      seo_title, meta_description, focus_keyword, canonical_url,
      og_title, og_description, status
    ) VALUES (
      ?, ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?,
      ?, ?, ?, ?,
      ?, ?, 'draft'
    )
    ON CONFLICT(slug) DO UPDATE SET
      title = excluded.title,
      category_slug = excluded.category_slug,
      organization = excluded.organization,
      job_type = excluded.job_type,
      location = excluded.location,
      qualification = excluded.qualification,
      salary = excluded.salary,
      experience = excluded.experience,
      positions = excluded.positions,
      last_date = excluded.last_date,
      no_deadline = excluded.no_deadline,
      publish_date = excluded.publish_date,
      official_link = excluded.official_link,
      apply_link = excluded.apply_link,
      is_verified = excluded.is_verified,
      featured = excluded.featured,
      logo_initial = excluded.logo_initial,
      featured_image = excluded.featured_image,
      image_alt = excluded.image_alt,
      excerpt = excluded.excerpt,
      content = excluded.content,
      seo_title = excluded.seo_title,
      meta_description = excluded.meta_description,
      focus_keyword = excluded.focus_keyword,
      canonical_url = excluded.canonical_url,
      og_title = excluded.og_title,
      og_description = excluded.og_description,
      status = 'draft',
      updated_at = CURRENT_TIMESTAMP;
  `)

  const stmtDailyInsert = db.prepare(`
    INSERT INTO daily_updates (
      slug, title, category, short_description, content,
      featured_image, image_alt, official_link, apply_link,
      deadline, no_deadline, publish_date, organization, location,
      qualification, experience, positions, job_type, salary,
      is_verified, featured, seo_title, meta_description,
      focus_keyword, canonical_url, og_title, og_description, status
    ) VALUES (
      ?, ?, ?, ?, ?,
      ?, ?, ?, ?,
      ?, ?, ?, ?, ?,
      ?, ?, ?, ?, ?,
      ?, ?, ?, ?,
      ?, ?, ?, ?, 'draft'
    )
    ON CONFLICT(slug) DO UPDATE SET
      title = excluded.title,
      category = excluded.category,
      short_description = excluded.short_description,
      content = excluded.content,
      featured_image = excluded.featured_image,
      image_alt = excluded.image_alt,
      official_link = excluded.official_link,
      apply_link = excluded.apply_link,
      deadline = excluded.deadline,
      no_deadline = excluded.no_deadline,
      publish_date = excluded.publish_date,
      organization = excluded.organization,
      location = excluded.location,
      qualification = excluded.qualification,
      experience = excluded.experience,
      positions = excluded.positions,
      job_type = excluded.job_type,
      salary = excluded.salary,
      is_verified = excluded.is_verified,
      featured = excluded.featured,
      seo_title = excluded.seo_title,
      meta_description = excluded.meta_description,
      focus_keyword = excluded.focus_keyword,
      canonical_url = excluded.canonical_url,
      og_title = excluded.og_title,
      og_description = excluded.og_description,
      status = 'draft',
      updated_at = CURRENT_TIMESTAMP;
  `)

  for (const item of oct12Articles) {
    console.log(`Saving draft: ${item.slug}`)
    const contentJson = JSON.stringify(item.content)

    stmtArtInsert.run(
      item.slug, item.title, item.category, item.organization, item.jobType, item.location,
      item.qualification, item.salary, item.experience, item.positions, item.lastDate, item.noDeadline ? 1 : 0,
      item.publishDate, item.officialLink, item.applyLink, item.isVerified ? 1 : 0, item.featured ? 1 : 0,
      item.logoInitial, item.featuredImage, item.imageAlt, item.excerpt, contentJson,
      item.seoTitle, item.metaDescription, item.focusKeyword, item.canonicalUrl, item.ogTitle, item.ogDescription
    )

    stmtDailyInsert.run(
      item.slug, item.title, item.categoryLabel, item.excerpt, contentJson,
      item.featuredImage, item.imageAlt, item.officialLink, item.applyLink,
      item.lastDate, item.noDeadline ? 1 : 0, item.publishDate, item.organization, item.location,
      item.qualification, item.experience, item.positions, item.jobType, item.salary,
      item.isVerified ? 1 : 0, item.featured ? 1 : 0, item.seoTitle, item.metaDescription,
      item.focusKeyword, item.canonicalUrl, item.ogTitle, item.ogDescription
    )
  }

  console.log('\nAll 10 article packages saved to SQLite as DRAFTS!')

  // Verify drafts in SQLite
  const draftArticles = db.prepare("SELECT id, slug, title, status FROM articles WHERE status = 'draft'").all()
  console.log(`\nVerified ${draftArticles.length} draft articles in 'articles' table:`)
  draftArticles.forEach(a => console.log(`  [ID ${a.id}] ${a.slug} (${a.status})`))

  const draftUpdates = db.prepare("SELECT id, slug, title, status FROM daily_updates WHERE status = 'draft'").all()
  console.log(`\nVerified ${draftUpdates.length} draft updates in 'daily_updates' table:`)
  draftUpdates.forEach(u => console.log(`  [ID ${u.id}] ${u.slug} (${u.status})`))
}

saveDrafts()
